/* ==========================================================================
   Mira Vasquez — Personal Landing Page
   ========================================================================== */

:root {
  --color-bg: #f4f6fb;
  --color-bg-alt: #eef1fa;
  --color-surface: #ffffff;
  --color-text: #1a1a2e;
  --color-text-muted: #565b73;
  --color-primary: #4361ee;
  --color-primary-dark: #1a1a2e;
  --color-accent: #7209b7;
  --color-border: #dde3f0;
  --radius: 12px;
  --max-width: 960px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Segoe UI", Roboto, Arial, sans-serif;
  line-height: 1.65;
  color: var(--color-text);
  background-color: var(--color-bg);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
}

ul {
  list-style: none;
}

h1, h2, h3 {
  line-height: 1.2;
  color: var(--color-primary-dark);
}

.section {
  padding: 48px 20px;
}

.section-alt {
  background-color: var(--color-bg-alt);
}

.section > h2 {
  max-width: var(--max-width);
  margin: 0 auto 24px;
  font-size: 1.7rem;
  position: relative;
  padding-bottom: 10px;
}

.section > h2::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 48px;
  height: 4px;
  background: var(--color-primary);
  border-radius: 2px;
}

/* ---------- HEADER / NAV ---------- */
.site-header {
  background-color: var(--color-primary-dark);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 10;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.logo {
  font-size: 1.4rem;
  font-weight: 700;
  color: #fff;
  text-decoration: none;
}

.logo-dot {
  color: var(--color-accent);
}

.site-header nav ul {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 18px;
}

.site-header nav a {
  color: #c7d3ff;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 2px solid transparent;
  padding-bottom: 2px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.site-header nav a:hover,
.site-header nav a:focus {
  color: #ffffff;
  border-bottom-color: #ffffff;
}

/* ---------- HERO ---------- */
.hero {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 56px 20px;
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  gap: 32px;
  text-align: center;
}

.eyebrow {
  color: var(--color-primary);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.85rem;
  margin-bottom: 8px;
}

.hero h1 {
  font-size: 2.4rem;
  margin-bottom: 16px;
}

.hero-tagline {
  color: var(--color-text-muted);
  max-width: 480px;
  margin: 0 auto 24px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 999px;
  font-weight: 700;
  text-decoration: none;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #fff;
}

.btn-primary:hover,
.btn-primary:focus {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px rgba(67, 97, 238, 0.35);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-outline:hover,
.btn-outline:focus {
  background-color: var(--color-primary);
  color: #fff;
  transform: translateY(-2px);
}

.hero-visual {
  position: relative;
  width: 200px;
  height: 200px;
  flex-shrink: 0;
}

.planet {
  position: absolute;
  inset: 40px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #a6c1ff, var(--color-primary) 60%, var(--color-primary-dark));
  box-shadow: 0 0 40px rgba(67, 97, 238, 0.5);
  animation: spin 18s linear infinite;
}

.orbit-ring {
  position: absolute;
  inset: 0;
  border: 2px dashed rgba(67, 97, 238, 0.35);
  border-radius: 50%;
  animation: spin 24s linear infinite;
}

.orbit-ring--small {
  inset: 20px;
  border-color: rgba(114, 9, 183, 0.3);
  animation-duration: 14s;
  animation-direction: reverse;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* ---------- ABOUT ---------- */
.about-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  color: var(--color-text-muted);
}

/* ---------- SKILLS ---------- */
.skills-row {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
}

.skill-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 22px;
  flex: 1 1 220px;
  max-width: 260px;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.skill-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(26, 26, 46, 0.08);
}

.skill-card h3 {
  color: var(--color-primary);
  margin-bottom: 8px;
  font-size: 1.1rem;
}

.skill-card p {
  color: var(--color-text-muted);
  font-size: 0.95rem;
}

/* ---------- PROJECTS ---------- */
.projects-gallery {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

.project-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.project-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 32px rgba(26, 26, 46, 0.12);
}

.project-card__media {
  height: 150px;
}

.project-card__media--one {
  background: linear-gradient(135deg, #4361ee, #7209b7);
}

.project-card__media--two {
  background: linear-gradient(135deg, #06b6d4, #4361ee);
}

.project-card__media--three {
  background: linear-gradient(135deg, #7209b7, #f72585);
}

.project-card__body {
  padding: 18px 20px;
  flex: 1;
}

.project-card__body h3 {
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.project-card__body p {
  color: var(--color-text-muted);
  font-size: 0.95rem;
}

/* ---------- CONTACT ---------- */
.contact-intro {
  max-width: var(--max-width);
  margin: 0 auto 24px;
  color: var(--color-text-muted);
}

.contact-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.contact-list li {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  padding: 14px 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
}

.contact-label {
  font-weight: 700;
  color: var(--color-primary-dark);
  min-width: 90px;
}

.contact-list a {
  text-decoration: none;
  font-weight: 600;
}

.contact-list a:hover,
.contact-list a:focus {
  text-decoration: underline;
}

/* ---------- FOOTER ---------- */
.site-footer {
  text-align: center;
  padding: 24px 16px;
  color: var(--color-text-muted);
  font-size: 0.9rem;
  background-color: var(--color-primary-dark);
}

.site-footer p {
  color: #c7d3ff;
}

/* ---------- RESPONSIVE ---------- */
@media (min-width: 640px) {
  .header-inner {
    flex-direction: row;
    justify-content: space-between;
  }

  .hero {
    flex-direction: row;
    text-align: left;
    padding: 80px 20px;
  }

  .hero-tagline {
    margin: 0 0 24px;
  }

  .hero-actions {
    justify-content: flex-start;
  }

  .hero h1 {
    font-size: 3rem;
  }

  .about-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 768px) {
  .projects-gallery {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ---------- ACCESSIBILITY: reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ==========================================================================
   Jonah Reyes — Responsive Portfolio Layout
   ========================================================================== */

:root {
  --color-bg: #f7f8fc;
  --color-bg-alt: #eef1fa;
  --color-surface: #ffffff;
  --color-text: #17182b;
  --color-text-muted: #565b73;
  --color-primary: #4361ee;
  --color-dark: #17182b;
  --color-accent: #f72585;
  --color-border: #dde3f0;
  --radius: 12px;
  --max-width: 1100px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Segoe UI", Roboto, Arial, sans-serif;
  line-height: 1.65;
  color: var(--color-text);
  background-color: var(--color-bg);
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

ul {
  list-style: none;
}

a {
  color: var(--color-primary);
}

h1, h2, h3 {
  color: var(--color-dark);
  line-height: 1.2;
}

.section {
  padding: 48px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-alt {
  background-color: var(--color-bg-alt);
  max-width: none;
}

.section-alt > * {
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

.section > h2,
.section-alt h2 {
  font-size: 1.7rem;
  margin-bottom: 24px;
  position: relative;
  padding-bottom: 10px;
}

.section > h2::after,
.section-alt h2::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 48px;
  height: 4px;
  background: var(--color-primary);
  border-radius: 2px;
}

/* ---------- HEADER / NAV (Flexbox) ---------- */
.site-header {
  background-color: var(--color-dark);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 20;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 16px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}

.logo {
  font-size: 1.2rem;
  font-weight: 700;
  color: #fff;
  text-decoration: none;
}

.logo-dot {
  color: var(--color-accent);
}

/* Hamburger button — hidden on wide screens, shown on narrow */
.nav-toggle {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 8px;
  order: 2;
}

.nav-toggle-bar {
  display: block;
  width: 100%;
  height: 2px;
  background-color: #fff;
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

/* Animate hamburger into an "X" when nav is open */
.nav-toggle[aria-expanded="true"] .nav-toggle-bar:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] .nav-toggle-bar:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] .nav-toggle-bar:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.primary-nav {
  order: 3;
  width: 100%;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.primary-nav.is-open {
  max-height: 300px;
}

.primary-nav ul {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 12px;
}

.primary-nav a {
  display: block;
  padding: 10px 4px;
  color: #c7d3ff;
  text-decoration: none;
  font-weight: 600;
  border-bottom: 2px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.primary-nav a:hover,
.primary-nav a:focus {
  color: #ffffff;
  border-bottom-color: #ffffff;
}

/* ---------- HERO ---------- */
.hero {
  text-align: center;
  padding: 56px 20px;
}

.eyebrow {
  color: var(--color-primary);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.85rem;
  margin-bottom: 12px;
}

.hero h1 {
  font-size: 2rem;
  margin-bottom: 16px;
}

.hero-sub {
  color: var(--color-text-muted);
  max-width: 520px;
  margin: 0 auto 24px;
}

.btn {
  display: inline-block;
  padding: 12px 26px;
  border-radius: 999px;
  font-weight: 700;
  text-decoration: none;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #fff;
}

.btn-primary:hover,
.btn-primary:focus {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px rgba(67, 97, 238, 0.35);
}

/* ---------- ABOUT ---------- */
.about-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 18px;
  color: var(--color-text-muted);
}

/* ---------- PROJECTS GRID (CSS Grid) ---------- */
.projects-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}

.project-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.project-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 32px rgba(23, 24, 43, 0.12);
}

.project-card--featured {
  grid-column: span 2;
}

.project-card__media {
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.project-card__media--one   { background: linear-gradient(135deg, #4361ee, #7209b7); }
.project-card__media--two   { background: linear-gradient(135deg, #06b6d4, #4361ee); }
.project-card__media--three { background: linear-gradient(135deg, #f72585, #7209b7); }
.project-card__media--four  { background: linear-gradient(135deg, #4cc9f0, #4361ee); }
.project-card__media--five  { background: linear-gradient(135deg, #7209b7, #4361ee); }

.project-card__body {
  padding: 18px 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.project-card__body h3 {
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.project-card__body p {
  color: var(--color-text-muted);
  font-size: 0.95rem;
  flex: 1;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.tag {
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

/* ---------- SKILLS (Flexbox) ---------- */
.skills-row {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  justify-content: center;
}

.skill-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 20px;
  flex: 1 1 200px;
  max-width: 240px;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.skill-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(23, 24, 43, 0.08);
}

.skill-card h3 {
  color: var(--color-primary);
  font-size: 1.05rem;
  margin-bottom: 6px;
}

.skill-card p {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

/* ---------- CONTACT ---------- */
.contact-intro {
  color: var(--color-text-muted);
  margin-bottom: 20px;
}

.contact-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.contact-list li {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  padding: 14px 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
}

.contact-label {
  font-weight: 700;
  min-width: 80px;
}

.contact-list a {
  text-decoration: none;
  font-weight: 600;
}

.contact-list a:hover,
.contact-list a:focus {
  text-decoration: underline;
}

/* ---------- FOOTER ---------- */
.site-footer {
  text-align: center;
  padding: 24px 16px;
  background-color: var(--color-dark);
  color: #c7d3ff;
  font-size: 0.9rem;
}

/* ---------- RESPONSIVE (mobile-first: nav-toggle shown by default above) ---------- */
@media (min-width: 768px) {
  .nav-toggle {
    display: none;
  }

  .primary-nav {
    order: 0;
    width: auto;
    max-height: none;
    overflow: visible;
  }

  .primary-nav ul {
    flex-direction: row;
    gap: 22px;
    padding-top: 0;
  }

  .primary-nav a {
    padding: 4px 2px;
  }

  .hero h1 {
    font-size: 2.6rem;
  }

  .about-content {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 1024px) {
  .hero {
    padding: 80px 20px;
  }

  .hero h1 {
    font-size: 3rem;
  }
}

/* ---------- ACCESSIBILITY: reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

// Responsive Portfolio Layout — mobile navigation toggle
// Opens/closes the primary nav on small screens and keeps the
// hamburger button's ARIA state in sync for screen readers.

document.addEventListener("DOMContentLoaded", () => {
  const navToggle = document.getElementById("navToggle");
  const primaryNav = document.getElementById("primaryNav");

  if (!navToggle || !primaryNav) return;

  const closeNav = () => {
    primaryNav.classList.remove("is-open");
    navToggle.setAttribute("aria-expanded", "false");
  };

  const toggleNav = () => {
    const isOpen = primaryNav.classList.toggle("is-open");
    navToggle.setAttribute("aria-expanded", String(isOpen));
  };

  navToggle.addEventListener("click", toggleNav);

  // Close the menu after a link is tapped, and when the viewport
  // grows past the mobile breakpoint the CSS already handles.
  primaryNav.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", () => {
      if (window.matchMedia("(max-width: 767px)").matches) {
        closeNav();
      }
    });
  });

  window.addEventListener("resize", () => {
    if (window.matchMedia("(min-width: 768px)").matches) {
      closeNav();
    }
  });
});

