:root {
  --bg: #0b0e1a;
  --panel: #141a30;
  --panel-2: #1e2540;
  --matched: #17331f;
  --border: #2a3358;
  --text: #e6ecff;
  --muted: #8b93b0;
  --accent: #4ade80;
  --accent-2: #60a5fa;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(ellipse at top, #16204a 0%, var(--bg) 60%);
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  padding: 2rem 1rem 4rem;
  text-align: center;
}

.app {
  max-width: 640px;
  margin: 0 auto;
}

header h1 {
  margin: 0 0 0.25rem;
  font-size: 1.75rem;
}

.subtitle {
  margin: 0 0 1.25rem;
  color: var(--muted);
}

.controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 1rem;
}

.difficulty-group {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.difficulty-btn {
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--muted);
  padding: 0.4rem 0.8rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.85rem;
}

.difficulty-btn.active {
  background: var(--panel-2);
  color: var(--text);
  border-color: var(--accent-2);
}

#restart-btn {
  padding: 0.45rem 1rem;
  border-radius: 8px;
  border: none;
  background: var(--accent-2);
  color: #08122a;
  font-weight: 600;
  cursor: pointer;
}

#restart-btn:hover {
  filter: brightness(1.08);
}

.stats-bar {
  display: flex;
  justify-content: center;
  gap: 1.5rem;
  color: var(--muted);
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
  font-size: 0.95rem;
}

.stats-bar strong {
  color: var(--text);
}

.board {
  display: grid;
  gap: 0.6rem;
  justify-content: center;
  margin: 0 auto 1rem;
}

.tile {
  width: 70px;
  height: 70px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  cursor: pointer;
  user-select: none;
  transition: transform 0.15s ease, background 0.15s ease;
}

.tile:hover:not(.revealed):not(.matched) {
  transform: translateY(-2px);
  border-color: var(--accent-2);
}

.tile.revealed {
  background: var(--panel-2);
  border-color: var(--accent-2);
}

.tile.matched {
  background: var(--matched);
  border-color: var(--accent);
  cursor: default;
}

.status {
  min-height: 1.5em;
  color: var(--accent);
  font-weight: 600;
}

@media (max-width: 480px) {
  .tile {
    width: 56px;
    height: 56px;
    font-size: 1.4rem;
  }
}

import { CartProvider } from "./context/CartContext";
import Header from "./components/Header";
import ProductGallery from "./components/ProductGallery";
import ProductInfo from "./components/ProductInfo";
import CartDrawer from "./components/CartDrawer";
import { product } from "./data/product";
import "./index.css";

export default function App() {
  return (
    <CartProvider>
      <Header />
      <main className="product-page">
        <ProductGallery images={product.gallery} />
        <ProductInfo product={product} />
      </main>
      <CartDrawer />
    </CartProvider>
  );
}

import { useState } from "react";

export default function ProductGallery({ images }) {
  const [activeIndex, setActiveIndex] = useState(0);
  const active = images[activeIndex];

  return (
    <div className="gallery">
      <div className="gallery-main" style={{ background: active.gradient }}>
        <span className="gallery-main-label">{active.label}</span>
      </div>
      <div className="gallery-thumbs">
        {images.map((image, index) => (
          <button
            key={image.id}
            type="button"
            className={`gallery-thumb ${index === activeIndex ? "gallery-thumb--active" : ""}`}
            style={{ background: image.gradient }}
            onClick={() => setActiveIndex(index)}
            aria-label={`Show ${image.label}`}
            aria-pressed={index === activeIndex}
          />
        ))}
      </div>
    </div>
  );
}

import { createContext, useContext, useMemo, useState, useCallback } from "react";

const CartContext = createContext(null);

export function CartProvider({ children }) {
  const [items, setItems] = useState([]); // { key, name, color, size, unitPrice, quantity }
  const [isDrawerOpen, setDrawerOpen] = useState(false);

  const addItem = useCallback((newItem) => {
    setItems((prev) => {
      const existing = prev.find((item) => item.key === newItem.key);
      if (existing) {
        return prev.map((item) =>
          item.key === newItem.key
            ? { ...item, quantity: item.quantity + newItem.quantity }
            : item
        );
      }
      return [...prev, newItem];
    });
    setDrawerOpen(true);
  }, []);

  const removeItem = useCallback((key) => {
    setItems((prev) => prev.filter((item) => item.key !== key));
  }, []);

  const updateQuantity = useCallback((key, quantity) => {
    setItems((prev) =>
      prev.map((item) => (item.key === key ? { ...item, quantity } : item))
    );
  }, []);

  const cartCount = useMemo(
    () => items.reduce((sum, item) => sum + item.quantity, 0),
    [items]
  );

  const cartTotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );

  const value = {
    items,
    addItem,
    removeItem,
    updateQuantity,
    cartCount,
    cartTotal,
    isDrawerOpen,
    setDrawerOpen,
  };

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
}

export function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) {
    throw new Error("useCart must be used inside a <CartProvider>");
  }
  return ctx;
}

import { useCart } from "../context/CartContext";

export default function CartDrawer() {
  const { items, isDrawerOpen, setDrawerOpen, removeItem, updateQuantity, cartTotal } =
    useCart();

  if (!isDrawerOpen) return null;

  return (
    <div className="drawer-overlay" onClick={() => setDrawerOpen(false)}>
      <aside className="drawer" onClick={(event) => event.stopPropagation()}>
        <div className="drawer-header">
          <h2>Your Cart</h2>
          <button
            type="button"
            className="drawer-close"
            onClick={() => setDrawerOpen(false)}
            aria-label="Close cart"
          >
            &times;
          </button>
        </div>

        {items.length === 0 ? (
          <p className="drawer-empty">Your cart is empty. Add something from the mission catalog!</p>
        ) : (
          <ul className="drawer-list">
            {items.map((item) => (
              <li key={item.key} className="drawer-item">
                <div>
                  <p className="drawer-item-name">{item.name}</p>
                  <p className="drawer-item-meta">
                    {item.color} / {item.size.toUpperCase()}
                  </p>
                  <p className="drawer-item-price">${item.unitPrice.toFixed(2)} each</p>
                </div>
                <div className="drawer-item-controls">
                  <label className="drawer-item-qty">
                    Qty
                    <select
                      value={item.quantity}
                      onChange={(event) =>
                        updateQuantity(item.key, Number(event.target.value))
                      }
                    >
                      {Array.from({ length: 10 }, (_, i) => i + 1).map((n) => (
                        <option key={n} value={n}>
                          {n}
                        </option>
                      ))}
                    </select>
                  </label>
                  <button
                    type="button"
                    className="drawer-item-remove"
                    onClick={() => removeItem(item.key)}
                  >
                    Remove
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}

        <div className="drawer-footer">
          <span>Total</span>
          <strong>${cartTotal.toFixed(2)}</strong>
        </div>
      </aside>
    </div>
  );
}

import { useState } from "react";
import ComposePost from "./components/ComposePost";
import PostCard from "./components/PostCard";
import { initialPosts } from "./data/posts";
import "./index.css";

export default function App() {
  const [posts, setPosts] = useState(initialPosts);

  function handlePublish(newPost) {
    setPosts((prev) => [newPost, ...prev]);
  }

  function handleToggleLike(postId) {
    setPosts((prev) =>
      prev.map((post) =>
        post.id === postId
          ? {
              ...post,
              liked: !post.liked,
              likes: post.liked ? post.likes - 1 : post.likes + 1,
            }
          : post
      )
    );
  }

  function handleAddComment(postId, text) {
    setPosts((prev) =>
      prev.map((post) =>
        post.id === postId
          ? {
              ...post,
              comments: [
                ...post.comments,
                { id: `c-${Date.now()}`, author: "You", text },
              ],
            }
          : post
      )
    );
  }

  return (
    <div className="feed-page">
      <header className="feed-header">
        <h1>Lumexa Orbit</h1>
        <p>See what the crew is building today.</p>
      </header>

      <ComposePost onPublish={handlePublish} />

      <div className="feed-list">
        {posts.map((post) => (
          <PostCard
            key={post.id}
            post={post}
            onToggleLike={handleToggleLike}
            onAddComment={handleAddComment}
          />
        ))}
      </div>
    </div>
  );
}

import { useState } from "react";

const GRADIENTS = [
  "linear-gradient(135deg, #f97316, #db2777)",
  "linear-gradient(135deg, #10b981, #0ea5e9)",
  "linear-gradient(135deg, #7c3aed, #db2777)",
  "linear-gradient(135deg, #f59e0b, #ef4444)",
];

function randomGradient() {
  return GRADIENTS[Math.floor(Math.random() * GRADIENTS.length)];
}

export default function ComposePost({ onPublish }) {
  const [text, setText] = useState("");

  function handleSubmit(event) {
    event.preventDefault();
    const trimmed = text.trim();
    if (trimmed === "") return;

    onPublish({
      id: `post-${Date.now()}`,
      author: "You",
      handle: "@you.orbit",
      avatarGradient: randomGradient(),
      timestamp: "just now",
      text: trimmed,
      imageGradient: null,
      likes: 0,
      liked: false,
      comments: [],
    });

    setText("");
  }

  return (
    <form className="compose-post" onSubmit={handleSubmit}>
      <textarea
        value={text}
        onChange={(event) => setText(event.target.value)}
        placeholder="Share a mission update with the crew..."
        rows={3}
      />
      <div className="compose-post-footer">
        <span className="compose-post-count">{text.length}/280</span>
        <button type="submit" disabled={text.trim() === ""}>
          Post
        </button>
      </div>
    </form>
  );
}

import { useState } from "react";

export default function CommentList({ comments, onAddComment }) {
  const [draft, setDraft] = useState("");

  function handleSubmit(event) {
    event.preventDefault();
    const trimmed = draft.trim();
    if (trimmed === "") return;
    onAddComment(trimmed);
    setDraft("");
  }

  return (
    <div className="comment-list">
      {comments.length > 0 && (
        <ul>
          {comments.map((comment) => (
            <li key={comment.id}>
              <strong>{comment.author}</strong> {comment.text}
            </li>
          ))}
        </ul>
      )}
      <form className="comment-form" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Write a comment..."
        />
        <button type="submit" disabled={draft.trim() === ""}>
          Reply
        </button>
      </form>
    </div>
  );
}

